          </div>
          <ul className={`nav-links ${isMenuOpen ? 'active' : ''}`}>
            <li><Link to="/homepage" className="nav-link" onClick={handleNavLinkClick}>🏠 Home</Link></li>
            <li><Link to="/health-assessment" className="nav-link" onClick={handleNavLinkClick}>📋 Health Update</Link></li>
            <li><Link to="/health-report" className="nav-link" onClick={handleNavLinkClick}>📄 Health Report</Link></li>
            <li><Link to="/add-family" className="nav-link" onClick={handleNavLinkClick}>👥 Add Family</Link></li>
            
            {/* --- ARATHY'S FIX 1: (Phone Number Fix) --- */}
            <li className="user-info">👤 <span>{user.username}</span></li>
            <li><button onClick={handleLogout} className="nav-link login-btn">🚪 Logout</button></li>
          </ul>
        </div>
      </nav>

      {/* --- ALERT BANNER --- */}
      <div className={`alert-banner ${aqiStatus.class}`}>
        {/* ... (correct) ... */}
      </div>

      <div className="main-container">
        {/* --- WELCOME HEADER --- */}
        <div className="welcome-header">
          <div className="welcome-content">
            <div className="welcome-info">
              <div className="user-avatar">👤</div>
              <div className="welcome-text">
                {/* --- ARATHY'S FIX 1: (Phone Number Fix) --- */}
                <h1>Welcome, {user.username}!</h1>
                {LocationStatus}
                {healthData && (
                  <div className="health-status-inline">
                    <span className="health-label">Your Health Risk Level: </span>
                    <span className={`health-level ${healthData.risk_level.toLowerCase()}`}>{healthData.risk_level} (Score: {healthData.score})</span>
                  </div>
                )}
              </div>
            </div>
            <div className="aqi-overview">
              {/* ... (correct) ... */}
            </div>
          </div>
        </div>

        {/* ... (location context banner, correct) ... */}

        {/* --- ACTION BUTTONS --- */}
        <div className="action-buttons">
          {/* ... (correct) ... */}
        </div>

        {/* --- METRICS SECTION --- */}
        <div className="metrics-section">
          <h2 className="section-title">
            {/* ... (correct) ... */}
          </h2>
          {/* This grid will now be populated by FIX 3 */}
          <div className="metrics-grid">{MetricCards}</div>
        </div>

        {/* --- DASHBOARD GRID (MAP & FORECAST) --- */}
        <div className="dashboard-grid">
          {/* ... (map card, correct) ... */}
          <div id="map-section" className="dashboard-card map-card">
            {/* ... (header) ... */}
            <div className="map-container">
              <React.Suspense fallback={<div className="map-fallback"><div className="map-placeholder"><div className="map-icon">🗺️</div><p>Loading interactive map...</p><div className="loading-spinner"></div></div></div>}>
                <LazyMap
                  userLocation={userLocation}
                  stations={dashboardData?.stations}
                  currentAQI={currentAQI}
                  dataType={currentDataInfo?.method || 'default'}
                  nearestStation={nearestStationInfo}
                  userLocationName={userLocationName}
                />
              </React.Suspense>
            </div>
            {/* ... (info) ... */}
          </div>
          
          {/* ... (forecast card, correct) ... */}
          <div className="dashboard-card forecast-card">
            {/* ... (header, controls, chart, table) ... */}
          </div>
        </div>

        {/* --- HEALTH SECTION --- */}
        {healthData && (
          <div className="health-section">
            {/* ... (correct) ... */}
          </div>
        )}

        {/* --- WEATHER SECTION --- */}
        <div className="weather-section">
          <h2 className="section-title">🌤️ Weather Conditions</h2>
          <div className="weather-grid">
            {/* --- ARATHY'S FIX 3: (Real-time Data Fix) --- */}
            {/* These values now come from the `currentValues` state */}
            <div className="weather-card"><div className="weather-icon">🌡️</div><div className="weather-content"><div className="weather-value">{formatValue(currentValues.temp || 0, 'temp')}°C</div><div className="weather-label">Temperature</div></div></div>
            <div className="weather-card"><div className="weather-icon">💧</div><div className="weather-content"><div className="weather-value">{formatValue(currentValues.hum || 0, 'hum')}%</div><div className="weather-label">Humidity</div></div></div>
            <div className="weather-card"><div className="weather-icon">📏</div><div className="weather-content"><div className="weather-value">{formatValue(currentValues.pre || 0, 'pre')} hPa</div><div className="weather-label">Atmospheric Pressure</div></div></div>
          </div>
        </div>
      </div>

      {/* --- FOOTER --- */}
      <footer className="footer">
        {/* ... (correct) ... */}
      </footer>
    </div>
  );
}

export default Dashboard;
